cat >> src/orchestration/tools/registry.test.ts <<'EOF'

describe('ToolRegistry.register', () => {
  it('throws naming the tool when a static inputSchema cannot be compiled', () => {
    const registry = new ToolRegistry();

    const register = () =>
      registry.register(
        {name: 'broken_probe', description: 'Probe tool', inputSchema: {type: 'object', properties: {n: {type: 'nope'}}}},
        async () => 'ok'
      );

    expect(register).toThrow(/broken_probe/);
  });
});
EOF
timeout 300 node --experimental-vm-modules node_modules/jest/bin/jest.js src/orchestration/tools/registry.test.ts 2>&1 | grep -E 'Tests:|✕|✓|Expected|Received' | head
